toolArgs.file_text:
@page "/dashboard"
@using sv_1d34748c83054fa48def96f88ec63e9c.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Current Site</h5>
            </div>
            <div class="card-body">
                <h4>@WarehouseState.CurrentWarehouseName</h4>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @AlertCardClass">
            <div class="card-header">
                <h5 class="mb-0">Low Stock Alerts</h5>
            </div>
            <div class="card-body text-center">
                <h1 class="display-3">@AlertService.CurrentLowStockCount</h1>
                <p>items below minimum level</p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Activity Log</h5>
            </div>
            <div class="card-body">
                <ul class="list-group list-group-flush">
                    @foreach (var entry in _log.TakeLast(10).Reverse())
                    {
                        <li class="list-group-item">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private readonly List<string> _log = new();

    private string AlertCardClass => AlertService.CurrentLowStockCount > 5 ? "border-danger" : "border-warning";

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        AlertService.StartPolling();
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Dashboard opened for {WarehouseState.CurrentWarehouseName}");
    }

    private void HandleWarehouseChanged()
    {
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.CurrentWarehouseName}");
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertChanged()
    {
        _log.Add($"[{DateTime.Now:HH:mm:ss}] Alert count updated: {AlertService.CurrentLowStockCount} low-stock items at {WarehouseState.CurrentWarehouseName}");
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
    }
}

